data class Rel(val slot:Long,val type:Long,val symbol:Sym?)
class Elf(val raw:ByteArray){private val b=ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);private fun u16(p:Int)=b.getShort(p).toInt()and 0xffff;private fun u32(p:Int)=b.getInt(p).toLong()and 0xffffffffL;private fun u64(p:Int)=b.getLong(p);private val segs:List<Seg>;val symbols:Map<String,Sym>;val rels:Map<Long,Rel>
 init{require(raw.size>=64&&raw[0]==0x7f.toByte()&&String(raw,1,3)=="ELF"&&raw[4]==2.toByte()&&raw[5]==1.toByte()&&u16(18)==183){"not AArch64 ELF64 LE"};segs=(0 until u16(56)).map{u64(32).toInt()+it*u16(54)}.filter{u32(it)==1L}.map{Seg(u64(it+8),u64(it+16),u64(it+32),u64(it+40))};val secs=(0 until u16(60)).map{u64(40).toInt()+it*u16(58)}.map{Sec(u32(it+4).toInt(),u64(it+24),u64(it+32),u32(it+40).toInt(),u64(it+56))};fun readSymbols(s:Sec):List<Sym>{require(s.entry==24L);val strings=secs[s.link];return (0 until(s.size/s.entry).toInt()).map{i->val p=(s.file+i*s.entry).toInt();val start=(strings.file+u32(p)).toInt();var end=start;while(raw[end]!=0.toByte())end++;Sym(String(raw,start,end-start),u64(p+8),u64(p+16),u16(p+6))}};val all=secs.filter{it.type==11}.flatMap(::readSymbols);symbols=all.filter{it.name.isNotEmpty()}.groupBy{it.name}.mapValues{(name,list)->val d=list.filter{it.section!=0};require(d.map{it.value to it.size}.distinct().size<=1){"conflicting $name"};d.firstOrNull()?:list.first()};val rm=mutableMapOf<Long,Rel>();secs.filter{it.type==4}.forEach{s->val linked=readSymbols(secs[s.link]);repeat((s.size/s.entry).toInt()){i->val p=(s.file+i*s.entry).toInt();val info=u64(p+8);val si=(info ushr 32).toInt();val r=Rel(u64(p),info and 0xffffffffL,if(si==0)null else linked[si]);require(rm.put(r.slot,r)==null){"duplicate ELF relocation"}}};rels=rm}
 private fun off(va:Long,n:Int):Int{val s=segs.filter{va>=it.virtual&&va+n<=it.virtual+it.fileSize};require(s.size==1){"unmapped 0x${va.toString(16)}"};return(s.single().file+va-s.single().virtual).toInt()}
