val candidate=doc("loader-candidate.toml");require(str(candidate.root.getValue("stock_elf_sha256"))==pinned&&str(candidate.root.getValue("stage"))=="reviewed-proposal"&&!bool(candidate.root.getValue("implementation_performed")));val layout=tab(candidate,"object_layout");val scopeObject=nval(layout,"scope");val calibration=scopeObject+nval(layout,"calibration_offset_from_scope");val adcObject=calibration+nval(layout,"adc_offset_from_calibration");val verticalObject=calibration+nval(layout,"vertical_offset_from_calibration");require(calibration==nval(layout,"calibration")&&adcObject==nval(layout,"adc")&&verticalObject==nval(layout,"vertical")){"candidate object arithmetic"};val destinationObjects=mapOf("lsb" to verticalObject,"vertical" to verticalObject,"adc" to adcObject);for(t in tabs(candidate,"destinations")){val id=sval(t,"id");val base=destinationObjects.getValue(id)+nval(t,"owner_offset");val length=nval(t,"length");require(nval(t,"base")==base&&nval(t,"end_exclusive")==base+length){"candidate destination $id"}}
val candidateCalls=tabs(candidate,"calls");require(candidateCalls.size==6);for(t in candidateCalls){val pc=nval(t,"pc");val op=nval(t,"opcode");require(elf.word(pc)==op);val plt=decodeBranch(pc,op);val slot=decodePltSlot(plt);require(slot==nval(t,"got_slot")){"candidate PLT slot"};val rel=requireNotNull(elf.rels[slot]);val symbol=sval(t,"symbol");require(rel.symbol?.name==symbol&&elf.symbols.getValue(symbol).value==nval(t,"target")){"candidate target"}}
val checkpointContract=mapOf(0L to Pair(0x2e57f8L,0x97fc6696L),1L to Pair(0x333b78L,0xb90077e0L),2L to Pair(0x333b84L,0xb90077e0L),3L to Pair(0x333b9cL,0xb90077e0L),4L to Pair(0x333ba8L,0x97fb9b9eL));val checkpoints=tabs(candidate,"checkpoints");require(checkpoints.size==5);for(t in checkpoints){val expected=checkpointContract.getValue(nval(t,"order"));require(nval(t,"pc")==expected.first&&nval(t,"opcode")==expected.second&&elf.word(expected.first)==expected.second){"candidate checkpoint"}}

